CREATE TABLE public.admin_users (user_id uuid PRIMARY KEY, email text NOT NULL, role text NOT NULL DEFAULT 'admin' CHECK (role='admin'), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.admin_users TO authenticated;
GRANT ALL ON public.admin_users TO service_role;
ALTER TABLE public.admin_users ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own admin membership" ON public.admin_users FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.admin_users WHERE user_id=auth.uid() AND role='admin') $$;
REVOKE ALL ON FUNCTION public.is_admin() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_admin() TO anon,authenticated,service_role;
CREATE POLICY "Admins list team" ON public.admin_users FOR SELECT TO authenticated USING(public.is_admin());
CREATE TABLE public.admin_activity (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), admin_email text NOT NULL, action text NOT NULL, target_type text NOT NULL, target_id text, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.admin_activity TO authenticated;
GRANT ALL ON public.admin_activity TO service_role;
ALTER TABLE public.admin_activity ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admins read activity" ON public.admin_activity FOR SELECT TO authenticated USING(public.is_admin());
CREATE POLICY "Admins record activity" ON public.admin_activity FOR INSERT TO authenticated WITH CHECK(public.is_admin() AND admin_email=(SELECT email FROM public.admin_users WHERE user_id=auth.uid()));
ALTER TABLE public.hire_requests ADD COLUMN status text NOT NULL DEFAULT 'New' CHECK(status IN ('New','Contacted','In Progress','Closed'));
DROP POLICY "Admins manage registrations" ON public.creator_registrations;
DROP POLICY "Admins read registrations" ON public.creator_registrations;
DROP POLICY "Admins read hiring enquiries" ON public.hire_requests;
GRANT SELECT,UPDATE,DELETE ON public.creator_registrations,public.brand_registrations,public.hire_requests TO authenticated;
GRANT ALL ON public.creator_registrations,public.brand_registrations,public.hire_requests TO service_role;
ALTER TABLE public.creator_registrations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.brand_registrations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.hire_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admin read creators" ON public.creator_registrations FOR SELECT TO authenticated USING(public.is_admin());
CREATE POLICY "Admin update creators" ON public.creator_registrations FOR UPDATE TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE POLICY "Admin delete creators" ON public.creator_registrations FOR DELETE TO authenticated USING(public.is_admin());
CREATE POLICY "Admin read brands" ON public.brand_registrations FOR SELECT TO authenticated USING(public.is_admin());
CREATE POLICY "Admin update brands" ON public.brand_registrations FOR UPDATE TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE POLICY "Admin delete brands" ON public.brand_registrations FOR DELETE TO authenticated USING(public.is_admin());
CREATE POLICY "Admin read hires" ON public.hire_requests FOR SELECT TO authenticated USING(public.is_admin());
CREATE POLICY "Admin update hires" ON public.hire_requests FOR UPDATE TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE POLICY "Admin delete hires" ON public.hire_requests FOR DELETE TO authenticated USING(public.is_admin());
CREATE FUNCTION public.remove_deleted_creator() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN DELETE FROM public.hire_requests WHERE creator_public_id=OLD.public_id; DELETE FROM public.public_creators WHERE public_id=OLD.public_id; RETURN OLD; END $$;
CREATE TRIGGER remove_deleted_creator BEFORE DELETE ON public.creator_registrations FOR EACH ROW EXECUTE FUNCTION public.remove_deleted_creator();
CREATE FUNCTION public.audit_admin_registration() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE actor text; verb text; target text; BEGIN SELECT email INTO actor FROM public.admin_users WHERE user_id=auth.uid(); IF actor IS NULL THEN RETURN coalesce(NEW,OLD); END IF; verb:=lower(TG_OP); IF TG_OP='UPDATE' AND TG_TABLE_NAME='creator_registrations' AND NEW.is_visible IS DISTINCT FROM OLD.is_visible THEN verb:=CASE WHEN NEW.is_visible THEN 'show' ELSE 'hide' END; END IF; target:=CASE WHEN TG_OP='DELETE' THEN OLD.id::text ELSE NEW.id::text END; INSERT INTO public.admin_activity(admin_email,action,target_type,target_id) VALUES(actor,verb,TG_TABLE_NAME,target); RETURN coalesce(NEW,OLD); END $$;
CREATE TRIGGER audit_creator_admin AFTER UPDATE OR DELETE ON public.creator_registrations FOR EACH ROW EXECUTE FUNCTION public.audit_admin_registration();
CREATE TRIGGER audit_brand_admin AFTER UPDATE OR DELETE ON public.brand_registrations FOR EACH ROW EXECUTE FUNCTION public.audit_admin_registration();
CREATE TRIGGER audit_hire_admin AFTER UPDATE OR DELETE ON public.hire_requests FOR EACH ROW EXECUTE FUNCTION public.audit_admin_registration();